mapper.select:
SELECT *
FROM
`inspection`.inspection_data_check  a
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`SHEET_ID` = #{params.SHEET_ID}

mapper.update:
UPDATE `inspection`.inspection_data_check a
SET
SHEET_ID=#{params.SHEET_ID}
,TASK_ID=#{params.TASK_ID}
,TASK_TYPE_DSCR=#{params.TASK_TYPE_DSCR}
,FILLING_DATE=#{params.FILLING_DATE}
,REPORT_NUM=#{params.REPORT_NUM}
,REGISTER_BOOK=#{params.REGISTER_BOOK}
,ANA_NUM=#{params.ANA_NUM}
,OTHER_NUM=#{params.OTHER_NUM}
,VALUE_1=#{params.VALUE_1}
,VALUE_2=#{params.VALUE_2}
,VALUE_3=#{params.VALUE_3}
,VALUE_4=#{params.VALUE_4}
,VALUE_5=#{params.VALUE_5}
,VALUE_6=#{params.VALUE_6}
,VALUE_7=#{params.VALUE_7}
,VALUE_8=#{params.VALUE_8}
,VALUE_9=#{params.VALUE_9}
,VALUE_10=#{params.VALUE_10}
,DEPARTMENT_HEAD=#{params.DEPARTMENT_HEAD}
,LEADER=#{params.LEADER}
,MEMBER=#{params.MEMBER}
,INSPECTED=#{params.INSPECTED}
,ATTACHMENT_NAME=#{params.ATTACHMENT_NAME}
,PAPER_ATTACHMENT=#{params.PAPER_ATTACHMENT}
,PRINT_ATTACHMENT=#{params.PRINT_ATTACHMENT}
,MODIFY_USERID=#{params.MODIFY_USERID}
,MODIFY_DATE=#{params.MODIFY_DATE}
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`SHEET_ID` = #{params.SHEET_ID}

mapper.select:
SELECT a.* ,c.name AS NAME, CONCAT(d.`guoku_dscr`,'统计数据核对情况检查表') AS SHEET_NAME, d.`guoku_dscr` as INSPECTED_DSCR FROM `inspection`.`inspection_data_check` a LEFT JOIN dmcode.`cm_guoku_dimnsn` d ON a.INSPECTED=d.`guoku_id` LEFT JOIN inspection.inspection_sysuser_talentpool_relation b ON b.SYS_USERID = a.ADD_USERID LEFT JOIN inspection.cm_guoku_talentpool c ON b.TALENTPOOL_ID = c.UUID where 1=1
AND a.TASK_ID = #{params.TASK_ID}
order by ADD_DATE,a.MODIFY_DATE desc

SELECT count(1) FROM    `inspection`.`inspection_data_check` a
where 1=1

    AND a.TASK_ID = #{params.TASK_ID}

SELECT * FROM    `inspection`.`inspection_data_check` a
where 1=1

    AND a.TASK_ID = #{params.TASK_ID}


    AND a.INSPECTED = #{params.INSPECTED}

